<?php
require_once('../path.php');
include(ROOT_PATH . '/app/database/db.php');
include(ROOT_PATH . '/assets/includes/auth_check.php');
$user_id=(int)$_SESSION['id'];$home_id=(int)$_SESSION['home_id'];$home_data=selectOne('homes',['id'=>$home_id])?:['name'=>''];$survey_user=selectOne('users',['id'=>$user_id])?:['first_name'=>''];
$conn->query("CREATE TABLE IF NOT EXISTS satisfaction_survey_responses (id INT UNSIGNED NOT NULL AUTO_INCREMENT,user_id INT NOT NULL,csat TINYINT UNSIGNED NOT NULL,nps TINYINT UNSIGNED NOT NULL,routine_score TINYINT UNSIGNED NOT NULL,most_used_feature VARCHAR(40) NOT NULL,feedback TEXT NULL,submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uniq_satisfaction_survey_user(user_id),CONSTRAINT fk_satisfaction_survey_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");
$stmt=$conn->prepare('SELECT id FROM satisfaction_survey_responses WHERE user_id=? LIMIT 1');$stmt->bind_param('i',$user_id);$stmt->execute();$submitted=(bool)$stmt->get_result()->fetch_assoc();$stmt->close();$error='';$success=false;
$features=['transactions'=>'הוספת פעולות','reports'=>'דוחות ותובנות','budgets'=>'תקציבים ויעדים','shopping'=>'רשימת קניות','work'=>'סידור עבודה','ai'=>'התזרים החכם'];
if($_SERVER['REQUEST_METHOD']==='POST'&&!$submitted){$csat=(int)($_POST['csat']??-1);$nps=(int)($_POST['nps']??-1);$routine=(int)($_POST['routine_score']??-1);$feature=(string)($_POST['most_used_feature']??'');$feedback=trim((string)($_POST['feedback']??''));if($csat<1||$csat>5||$nps<1||$nps>5||$routine<1||$routine>5||!isset($features[$feature])){$error='נשאר עוד פרט קטן להשלים.';}elseif(mb_strlen($feedback)>2000){$error='אפשר לקצר את התשובה הפתוחה עד 2,000 תווים.';}else{$stmt=$conn->prepare('INSERT INTO satisfaction_survey_responses(user_id,csat,nps,routine_score,most_used_feature,feedback) VALUES(?,?,?,?,?,?)');$stmt->bind_param('iiiiss',$user_id,$csat,$nps,$routine,$feature,$feedback);try{$stmt->execute();$success=true;$submitted=true;}catch(mysqli_sql_exception $e){if($e->getCode()===1062)$submitted=true;else throw $e;}$stmt->close();}}
function sh($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
