5px solid #29b669;box-shadow:0 7px 18px rgba(38,51,73,.24);cursor:grab}.survey-mood-slider input[type=range]::-moz-range-thumb{width:24px;height:24px;border-radius:50%;background:#fff;border:5px solid #29b669;box-shadow:0 7px 18px rgba(38,51,73,.24)}.survey-mood-bubble{position:absolute;top:0;left:var(--mood-left,50%);transform:translateX(-50%);width:52px;height:52px;border-radius:18px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:2rem;box-shadow:0 10px 25px rgba(38,51,73,.17);transition:left .12s ease,transform .12s ease}.survey-mood-bubble::after{content:'';position:absolute;bottom:-7px;border:8px solid transparent;border-top-color:#fff;border-bottom:0}.survey-mood-bubble.is-moving{transform:translateX(-50%) scale(1.13) rotate(-4deg)}.survey-mood-slider .survey-hint{margin-top:12px;margin-bottom:0}.survey-scale input,.survey-feature input{position:absolute;opacity:0;pointer-events:none}.survey-scale label{aspect-ratio:1;display:flex;align-items:center;justify-content:center;border:1px solid #e1e6ed;border-radius:13px;background:#fff;font-weight:800;cursor:pointer;transition:.18s}.survey-scale input:checked+label{background:var(--main);color:#fff;border-color:var(--main);transform:translateY(-3px);box-shadow:0 8px 18px rgba(41,182,105,.25)}.survey-features{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.survey-feature label{display:flex;align-items:center;gap:9px;border:1px solid #e1e6ed;border-radius:16px;padding:13px 15px;font-weight:700;cursor:pointer}.survey-feature input:checked+label{border-color:var(--main);background:var(--sub_main-light);color:var(--main)}.survey-feature i{width:24px;text-align:center}.survey-textarea{width:100%;min-height:120px;box-sizing:border-box;border:1px solid #e1e6ed;border-radius:18px;padding:15px;font:inherit;resize:vertical}.survey-submit{width:100%;border:0;border-radius:999px;background:linear-gradient(135deg,#29b669,#20a760);color:#fff;font:inherit;font-weight:900;font-size:1.05rem;padding:15px;margin-top:24px;cursor:pointer;box-shadow:0 12px 28px rgba(41,182,105,.25)}.survey-complete{text-align:center;padding:50px 20px}.survey-complete__icon{width:84px;height:84px;margin:auto;background:var(--sub_main-light);color:var(--main);border-radius:26px;display:flex;align-items:center;justify-content:center;font-size:2.5rem}.survey-complete h2{font-size:1.8rem;color:#263349;margin:18px 0 8px}.survey-complete p{color:#768096;margin:0 0 22px}.survey-back{display:inline-flex;gap:8px;align-items:center;text-decoration:none;background:#263349;color:#fff;border-radius:999px;padding:12px 22px;font-weight:800}.survey-error{background:#fee2e2;color:#b42318;border-radius:14px;padding:11px;text-align:center;margin-bottom:18px;font-weight:700}@media(max-width:620px){.survey-scale,.survey-scale--11{grid-template-columns:repeat(5,1fr)}.survey-features{grid-template-columns:1fr}.survey-page{padding-top:18px}.survey-brand img{width:135px}}
</style></head><body><main class="survey-page"><div class="survey-shell"><div class="survey-brand"><img src="<?php echo BASE_URL;?>assets/images/tazrim-logo-ver.png" alt="התזרים"></div><header class="survey-hero"><span class="survey-kicker"><i class="fa-solid fa-heart"></i> שתי דקות שמשפרות את התזרים</span><h1>סקר שביעות רצון</h1><p>היי <?php echo sh($survey_user['first_name'] ?: 'שם');?>, נשמח לשמוע כמה מילים</p></header><section class="survey-card">
<?php if($submitted):?><div class="survey-complete"><div class="survey-complete__icon"><i class="fa-solid fa-check"></i></div><h2><?php echo $success?'תודה, קיבלנו 💚':'כבר ענית על הסקר';?></h2><p><?php echo $success?'התשובות שלך יעזרו לנו לבנות מוצר טוב יותר.':'כל משתמש יכול לענות פעם אחת בלבד. תודה על הזמן שלך.';?></p><a class="survey-back" href="<?php echo BASE_URL;?>index.php">חזרה להתזרים</a></div><?php else:?><?php if($error):?><div class="survey-error"><?php echo sh($error);?></div><?php endif;?><form method="post" id="survey-form">
<div class="survey-question"><h2>עד כמה אתם מרוצים מהתזרים?</h2><div class="survey-mood-slider" id="survey-mood-slider"><div class="survey-mood-bubble" id="survey-mood-bubble" aria-hidden="true">🙂</div><input type="range" name="csat" id="survey-csat" min="1" max="5" step="1" value="3" required><div class="survey-hint survey-hint--scale"><span>לא מרוצה</span><span>מרוצה מאוד</span></div></div></div>
<?php $qs=[['nps','כמה סביר שתמליצו עלינו לחבר?',1,5,'לא סביר','סביר מאוד'],['routine_score','עד כמה התזרים הוא חלק מהשגרה בבית?',1,5,'כמעט לא','חלק קבוע']];foreach($qs as $q):?><div class="survey-question"><h2><?php echo $q[1];?></h2><div class="survey-hint survey-hint--scale"><span><?php echo $q[4];?></span><span><?php echo $q[5];?></span></div><div class="survey-scale"><?php for($i=$q[2];$i<=$q[3];$i++):?><span><input type="radio" name="<?php echo $q[0];?>" id="<?php echo $q[0].$i;?>" value="<?php echo $i;?>" required><label for="<?php echo $q[0].$i;?>"><?php echo $i;?></label></span><?php endfor;?></div></div><?php endforeach;?>
<div class="survey-question"><h2>במה אתם משתמשים הכי הרבה?</h2><div class="survey-features"><?php $icons=['transactions'=>'fa-receipt','reports'=>'fa-chart-line','budgets'=>'fa-bullseye','shopping'=>'fa-cart-shopping','work'=>'fa-calendar-week','ai'=>'fa-wand-magic-sparkles'];foreach($features as $k=>$v):?><span class="survey-feature"><input type="radio" name="most_used_feature" id="feature-<?php echo $k;?>" value="<?php echo $k;?>" required><label for="feature-<?php echo $k;?>"><i class="fa-solid <?php echo $icons[$k];?>"></i><?php echo $v;?></label></span><?php endforeach;?></div></div><div class="survey-question"><h2>מה הדבר האחד שהייתם משפרים?</h2><div class="survey-hint">אפשר לכתוב בחופשיות, ואפשר גם להשאיר ריק</div><textarea class="survey-textarea" name="feedback" maxlength="2000" placeholder="הייתי שמח אם..."></textarea></div><button class="survey-submit" type="submit">שליחת הסקר</button></form><?php endif;?></section></div></main><script>var moodInput=document.getElementById('survey-csat'),moodBubble=document.getElementById('survey-mood-bubble'),moodTimer;if(moodInput&&moodBubble){var moods=['😞','🙁','😐','🙂','🤩'];function paintMood(moving){var v=Number(moodInput.value),pct=(v-1)/4*100;moodBubble.textContent=moods[v-1];moodBubble.style.setProperty('--mood-left','calc('+pct+'% + '+(17-pct*.34)+'px)');moodBubble.classList.toggle('is-moving',!!moving);}moodInput.addEventListener('input',function(){paintMood(true);clearTimeout(moodTimer);moodTimer=setTimeout(function(){paintMood(false)},140);});moodInput.addEventListener('change',function(){paintMood(false);});paintMood(false);}</script></body></html>
